package com.cekalix.dao;
import com.cekalix.modelo.Venta;import com.cekalix.util.ConexionBD;import java.sql.*;import java.math.*;import java.util.*;
public class VentaDAO {
 public int registrar(int cliente,int usuario,String tipo,String pago,int[] ids,int[] cantidades)throws SQLException{
  if(ids==null||ids.length==0||ids.length!=cantidades.length)throw new SQLException("Agrega productos.");try(Connection c=ConexionBD.obtenerConexion()){c.setAutoCommit(false);try{BigDecimal sub=BigDecimal.ZERO;List<BigDecimal> precios=new ArrayList<>();for(int i=0;i<ids.length;i++){if(cantidades[i]<1)throw new SQLException("Cantidad inválida.");try(PreparedStatement p=c.prepareStatement("SELECT precio,stock FROM producto WHERE id_producto=? AND estado=1 FOR UPDATE")){p.setInt(1,ids[i]);try(ResultSet r=p.executeQuery()){if(!r.next()||r.getInt("stock")<cantidades[i])throw new SQLException("Producto inexistente o stock insuficiente.");BigDecimal pr=r.getBigDecimal("precio");precios.add(pr);sub=sub.add(pr.multiply(BigDecimal.valueOf(cantidades[i])));}}}BigDecimal igv=sub.multiply(new BigDecimal("0.18")).setScale(2,RoundingMode.HALF_UP),total=sub.add(igv);int num;try(PreparedStatement p=c.prepareStatement("SELECT COALESCE(MAX(numero),0)+1 FROM venta WHERE tipo_comprobante=?")){p.setString(1,tipo);try(ResultSet r=p.executeQuery()){r.next();num=r.getInt(1);}}int id;try(PreparedStatement p=c.prepareStatement("INSERT INTO venta(id_cliente,id_usuario,tipo_comprobante,serie,numero,metodo_pago,subtotal,igv,total) VALUES(?,?,?,?,?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){p.setInt(1,cliente);p.setInt(2,usuario);p.setString(3,tipo);p.setString(4,"FACTURA".equals(tipo)?"F001":"B001");p.setInt(5,num);p.setString(6,pago);p.setBigDecimal(7,sub);p.setBigDecimal(8,igv);p.setBigDecimal(9,total);p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){r.next();id=r.getInt(1);}}for(int i=0;i<ids.length;i++){BigDecimal line=precios.get(i).multiply(BigDecimal.valueOf(cantidades[i]));try(PreparedStatement p=c.prepareStatement("INSERT INTO detalle_venta(id_venta,id_producto,cantidad,precio_unitario,subtotal) VALUES(?,?,?,?,?)")){p.setInt(1,id);p.setInt(2,ids[i]);p.setInt(3,cantidades[i]);p.setBigDecimal(4,precios.get(i));p.setBigDecimal(5,line);p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("UPDATE producto SET stock=stock-? WHERE id_producto=?")){p.setInt(1,cantidades[i]);p.setInt(2,ids[i]);p.executeUpdate();}}c.commit();return id;}catch(Exception e){c.rollback();if(e instanceof SQLException se)throw se;throw new SQLException(e);}finally{c.setAutoCommit(true);}}
 }
 public List<Venta> listar()throws SQLException{List<Venta> l=new ArrayList<>();String q="SELECT v.*,c.razon_social FROM venta v JOIN cliente c ON c.id_cliente=v.id_cliente ORDER BY v.fecha DESC";try(Connection c=ConexionBD.obtenerConexion();PreparedStatement p=c.prepareStatement(q);ResultSet r=p.executeQuery()){while(r.next()){Venta v=new Venta();v.setIdVenta(r.getInt("id_venta"));v.setNumero(r.getInt("numero"));v.setComprobante(r.getString("tipo_comprobante"));v.setMetodoPago(r.getString("metodo_pago"));v.setEstado(r.getString("estado"));v.setFecha(r.getTimestamp("fecha").toLocalDateTime());v.setTotal(r.getBigDecimal("total"));v.setCliente(r.getString("razon_social"));l.add(v);}}return l;}
}